async _installDirect() {
  this.#signal.addEventListener("abort", this.cancel, { once: true });
  try {
    this._installer = await lazy.AddonManager.getInstallForURL(this._url, {
      name: this._name,
    });
    this._installer.promptHandler = this.prompt;
    await this._installer.install(); // throws, if failed
  } finally {
    this.#signal.removeEventListener("abort", this.cancel, { once: true });
    delete this._installer;
  }

cancel = () => {
  if (this._installer) {
    try {
      this._installer.cancel();
    } catch (e) {
      // if install failed
      gAccountSetupLogger.warn(e);
    }
  }
};

async #installAddon() {
  const addon = this.#currentConfig.addons[0];
  this.abortable = new AbortController();
  const installer = new AddonInstaller(addon, this.abortable.signal);
  await installer.install();
  this.abortable = null;
}

async #getExchangeAddons(config) {
  this.abortable = new AbortController();
  try {
    config = await lazy.getAddonsList(config, this.abortable.signal);
    return config;
  } catch (error) {
    // We reject here, but this will silently fail as we don't need to
    // show the user if we were unable to find add-ons for the config.
    gAccountSetupLogger.error(`getExchangeAddons failed:`, error);
    throw error;
  } finally {
    this.abortable = null;
  }
